// Playlist: https://www.shadertoy.com/playlist/mfdGWj

// Dialation with Rigid PGA is heavily dependent on the reference frame, as it's
// effectively a uniform scaling of space. 

// More advanced dialation requires moving to conformal PGA, but that tends to get 
// pricy very quick.

// This example works within the limitations of dialation in a strictly rigid 
// projective geometric algebra.

// A plane joins three points
vec4 join(vec3 p, vec3 q, vec3 r) {
    vec4 trivec;
    trivec.xyz = cross(q - p, r - p); // plane normal
    trivec.w = -dot(trivec.xyz, p); // plane offset

    trivec /= length(trivec.xyz);
    return trivec;
}

// The scalar orientation found by meeting a point and plane together.
// This is effectively a half-plane check.
float meet(vec4 p, vec4 g)
{
    return dot(p, g);
}

// Allows the planes of the tetrahedron to be scaled by their bulk components.
float meetPointTetrahedron(vec3 p, vec3 a, vec3 b, vec3 c, vec3 d, float tetBlkScale, float ptBlkScale)
{
    // Recover p's 4D vector 
    vec4 pv = vec4(p, ptBlkScale);

    // Construct the four trivector bases defining the tetrahedron.
    vec4 ga = join(a, b, c);
    vec4 gb = join(b, d, c);
    vec4 gc = join(c, d, a);
    vec4 gd = join(d, b, a);

    // Now scale the bulk norms of the planes.
    ga.w *= tetBlkScale;
    gb.w *= tetBlkScale;
    gc.w *= tetBlkScale;
    gd.w *= tetBlkScale;

    // Meet the point with the four planes. 
    vec4 meet4 = vec4(
        meet(pv, ga),
        meet(pv, gb),
        meet(pv, gc),
        meet(pv, gd)
    );

    // If any are negative, the point lies outside the tetrahedron.
    if (any(lessThan(meet4, vec4(0.0)))) return -1.0;
    return 1.0;
}


#define OUTLINE_WIDTH .01

#define M2PI 6.28318530718

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 2   // make this 2 or 3 for antialiasing
#endif

struct Payload {
    float d; // distance
    vec3 albedo; // albedo
};

const float lineThickness = .002;
const float arrowThickness = .002;
const float arrowCapWidth = .06;
const float arrowCapHeight = .12;

const float xLength = 2.0;
const float yLength = 8./3.;
