void getTetrahedron(out vec3 a, out vec3 b, out vec3 c, out vec3 d) {
    float s = 0.2; // speed of animation
    float tsc = .45;

    //vec3 rotationAxis = vec3(1.0, sin(iTime * s) * .5, 1.0);
    //vec3 rotationAxis = vec3(0.0, 0.0, 1.0);
    vec3 rotationAxis = vec3(1.0*sin(iTime * s), 1.0, 1.0);
    vec3 up = vec3(0.0, 1.0, 0.0);
    vec3 right = normalize(cross(up, rotationAxis)) * 1.0;

    mat3 rot = rotationMatrix(rotationAxis, iTime * s * .5);

    a = right * rotationMatrix(rotationAxis, iTime * s * .5 + M2PI * .33)*1.;// + vec3(0., yLength*.5, wPlaneHeight);
    b = right * rotationMatrix(rotationAxis, iTime * s * .5 + M2PI * .66)*1.;// + vec3(0., yLength*.5, wPlaneHeight);
    c = right * rotationMatrix(rotationAxis, iTime * s * .5 + M2PI * .99)*1.;// + vec3(0., yLength*.5, wPlaneHeight);

    vec3 n = normalize(cross(b-a, c-a))*0.7;
    vec3 cen = (a + b + c) / 3.0;
    d = cen + n;
    a -= n;
    b -= n;
    c -= n;

    cen = (a + b + c + d) / 4.0;
    a -= cen; b -= cen; c -= cen; d -= cen;

    a *= tsc; b *= tsc; c *= tsc; d *= tsc;
}

float getVecBulkScale() {
    float s = .4; // anim speed
    //return 1.0;
    return 1.0 + (pow(sin(s*iTime), 2.0) * 2.0);
}

float getTetBulkScale() {
    float s = .3; // anim speed
    //return 1.0;
    return 1.0 + (pow(cos(s*iTime), 2.0) * 2.0);
}

vec3 getPoint() {
    float s = 0.3;// 2.1; // anim speed

    vec3 a, b, c, d;
    getTetrahedron(a, b, c, d);
    vec3 cen = (a + b + c + d) / 4.0;

    //return cen + normalize(vec3(1.0, -1.0, 1.0));

    return cen + cos(s*iTime*vec3(1.0,-1.1,1.2)+vec3(0.0,1.0,2.0)) * .8;
}

Payload map(in vec3 ro, vec3 rd) {
    Payload res;
    res.d = 1e38f;
    res.albedo = vec3(0.0);

    vec3 a, b, c, d;
    getTetrahedron(a, b, c, d);

    // Query point
    vec3 p = getPoint();

    // Find where the point meets the trivector, whose bulk is scaled.
    float mpt = meetPointTetrahedron(p, a, b, c, d, getTetBulkScale(), getVecBulkScale()); 

    // Use meet to color the point.
    float sigmoid = 1.f / (1.f + exp(-mpt));
    vec3 color = mix(emerald, green, sigmoid);
    {
        float d = sdSphere(ro - p.xyz, .1);
        if (d < res.d) {res.d = d; res.albedo = mpt > 0.0 ? blue : purple;}
    }


    // Visualization code:
    vec3 a2 = a * getTetBulkScale();
    vec3 b2 = b * getTetBulkScale();
    vec3 c2 = c * getTetBulkScale();
    vec3 d2 = d * getTetBulkScale();


    // Outlines of tetrahedron
    {
    // Visualize triangle edges
    {        
        // Opaque outline
        float dis = 1e38f;

        dis = min(dis, sdCapsule( ro, a, b, 0.01 ));
        dis = min(dis, sdCapsule( ro, a, c, 0.01 ));
        dis = min(dis, sdCapsule( ro, a, d, 0.01 ));

        dis = min(dis, sdCapsule( ro, b, c, 0.01 ));
        dis = min(dis, sdCapsule( ro, b, d, 0.01 ));

        dis = min(dis, sdCapsule( ro, c, d, 0.01 ));

        if (dis < res.d) {res.d = dis; res.albedo = color;}
    }



    // Visualize bulk expansion triangle edges
    {        
        // Opaque outline
        float dis = 1e38f;
        dis = min(dis, sdCapsule( ro, a2, b2, 0.01 ));
        dis = min(dis, sdCapsule( ro, a2, c2, 0.01 ));
        dis = min(dis, sdCapsule( ro, a2, d2, 0.01 ));

        dis = min(dis, sdCapsule( ro, b2, c2, 0.01 ));
        dis = min(dis, sdCapsule( ro, b2, d2, 0.01 ));

        dis = min(dis, sdCapsule( ro, c2, d2, 0.01 ));

        if (dis < res.d) {res.d = dis; res.albedo = color;}
    }
    }

    // Visualizing where point meets the half planes, which are scaled by the bulk.
    {
        float dis = 1e38f;
        vec3 cpa = closestPlane( a2, b2, c2, p.xyz );
        vec3 cpb = closestPlane( b2, c2, d2, p.xyz );
        vec3 cpc = closestPlane( c2, d2, a2, p.xyz );
        vec3 cpd = closestPlane( d2, b2, a2, p.xyz );

        // Construct the four trivector bases defining the tetrahedron.
        vec4 ga = join(a, b, c);
        vec4 gb = join(b, d, c);
        vec4 gc = join(c, d, a);
        vec4 gd = join(d, b, a);

        // Modify the bulk
        ga.w *= getTetBulkScale();
        gb.w *= getTetBulkScale();
        gc.w *= getTetBulkScale();
        gd.w *= getTetBulkScale();

        // Meet the point with the four planes. 
        vec4 mpk = vec4(
            meet(vec4(p, getVecBulkScale()), ga),
            meet(vec4(p, getVecBulkScale()), gb),
            meet(vec4(p, getVecBulkScale()), gc),
            meet(vec4(p, getVecBulkScale()), gd)
        );


        // for illustrative purposes...
        vec4 qv = vec4(p, getVecBulkScale());
        float d0 = meet(vec4(qv.xyz, 1.0), ga) - meet(vec4(qv.xyz, qv.w), ga);
        float d1 = meet(vec4(qv.xyz, 1.0), gb) - meet(vec4(qv.xyz, qv.w), gb);
        float d2 = meet(vec4(qv.xyz, 1.0), gc) - meet(vec4(qv.xyz, qv.w), gc);
        float d3 = meet(vec4(qv.xyz, 1.0), gd) - meet(vec4(qv.xyz, qv.w), gd);


        dis = min(dis, sdCapsule( ro, p.xyz, cpa /*+ normalize(cpa - p.xyz) * abs(d0)*/, 0.01 ));
        if (dis < res.d) {res.d = dis; res.albedo = mpk.x > 0.0 ? blue : purple;}

        dis = min(dis, sdCapsule( ro, p.xyz, cpb /*+ normalize(cpb - p.xyz) * abs(d1)*/, 0.01 ));
        if (dis < res.d) {res.d = dis; res.albedo = mpk.y > 0.0 ? blue : purple;}

        dis = min(dis, sdCapsule( ro, p.xyz, cpc /*+ normalize(cpc - p.xyz) * abs(d2)*/, 0.01 ));
        if (dis < res.d) {res.d = dis; res.albedo = mpk.z > 0.0 ? blue : purple;}

        dis = min(dis, sdCapsule( ro, p.xyz, cpd /*+ normalize(cpd - p.xyz) * abs(d3)*/, 0.01 ));
        if (dis < res.d) {res.d = dis; res.albedo = mpk.w > 0.0 ? blue : purple;}


    }



    return res;
}

vec4 over(vec4 a, vec4 b) {
  vec4 result;
  result.a = a.a + b.a * (1.f - a.a);
  if (result.a == 0.f)
    return a;   // avoid NaN
  result.rgb = (a.rgb * a.a + b.rgb * b.a * (1.f - a.a)) / result.a;
  return result;
}

vec3 scene(in vec3 ro,in vec3 rd) {
    vec3 col = vec3(1.0);		// initialize color return value

    vec3 roStart = ro;

    vec3 a, b, c, d;
    getTetrahedron(a, b, c, d);   

    vec3 q = getPoint();
    vec4 qv = vec4(q, getVecBulkScale());

    // Construct the four trivector bases defining the tetrahedron.
    vec4 ga = join(a, b, c);
    vec4 gb = join(b, d, c);
    vec4 gc = join(c, d, a);
    vec4 gd = join(d, b, a);

    vec3 a2 = a * getTetBulkScale();
    vec3 b2 = b * getTetBulkScale();
    vec3 c2 = c * getTetBulkScale();
    vec3 d2 = d * getTetBulkScale();

    vec4 ga2 = join(a2, b2, c2);
    vec4 gb2 = join(b2, d2, c2);
    vec4 gc2 = join(c2, d2, a2);
    vec4 gd2 = join(d2, b2, a2);

    vec4 tuvs[10];

    tuvs[0].w = 0.0;
    tuvs[1].w = 1.0;
    tuvs[2].w = 2.0;
    tuvs[3].w = 3.0;
    tuvs[4].w = 4.0;
    tuvs[5].w = 5.0;
    tuvs[6].w = 6.0;
    tuvs[7].w = 7.0;
    tuvs[8].w = 8.0;
    tuvs[9].w = 9.0;

    // Spheres around the query point determining containment
    vec3 cpa = closestPlane( a, b, c, q.xyz );
    vec3 cpb = closestPlane( b, c, d, q.xyz );
    vec3 cpc = closestPlane( c, d, a, q.xyz );
    vec3 cpd = closestPlane( d, b, a, q.xyz );

    tuvs[0].y = distance(q.xyz, cpa);
    tuvs[1].y = distance(q.xyz, cpb);
    tuvs[2].y = distance(q.xyz, cpc);
    tuvs[3].y = distance(q.xyz, cpd);


    // Faces of the tetrahedron and metadata    
    {
        // Meet the dialated point with the four non-dialated planes. 
        tuvs[0].z = meet(qv, ga); 
        tuvs[1].z = meet(qv, gb); 
        tuvs[2].z = meet(qv, gc); 
        tuvs[3].z = meet(qv, gd);

        tuvs[0].x = triIntersect(ro, rd, a, b, c).x;
        tuvs[1].x = triIntersect(ro, rd, b, c, d).x;
        tuvs[2].x = triIntersect(ro, rd, c, d, a).x;
        tuvs[3].x = triIntersect(ro, rd, d, a, b).x;

        // Meet the dialated point with the four dialated planes. 
        tuvs[4].z = meet(qv, ga2);
        tuvs[5].z = meet(qv, gb2);
        tuvs[6].z = meet(qv, gc2);
        tuvs[7].z = meet(qv, gd2);

        tuvs[4].x = triIntersect(ro, rd, a2, b2, c2).x;
        tuvs[5].x = triIntersect(ro, rd, b2, c2, d2).x;
        tuvs[6].x = triIntersect(ro, rd, c2, d2, a2).x;
        tuvs[7].x = triIntersect(ro, rd, d2, a2, b2).x;
    }


    // "Dialated" vector projecting down to our 3D query point. 
    vec3 qColor = (all(greaterThan(vec4(tuvs[4].z, tuvs[5].z, tuvs[6].z, tuvs[7].z), vec4(0.0)))) ? blue : purple; // todo, meet...

    vec4 g0, g1, g2, g3;

    {
        // for illustrative purposes...
        float d0 = meet(vec4(qv.xyz, 1.0), ga2) - meet(vec4(qv.xyz, qv.w), ga2);
        float d1 = meet(vec4(qv.xyz, 1.0), gb2) - meet(vec4(qv.xyz, qv.w), gb2);
        float d2 = meet(vec4(qv.xyz, 1.0), gc2) - meet(vec4(qv.xyz, qv.w), gc2);
        float d3 = meet(vec4(qv.xyz, 1.0), gd2) - meet(vec4(qv.xyz, qv.w), gd2);

        g0 = vec4(-normalize(cpa - qv.xyz), 0.0); g0.w = d0;
        g1 = vec4(-normalize(cpb - qv.xyz), 0.0); g1.w = d1;
        g2 = vec4(-normalize(cpc - qv.xyz), 0.0); g2.w = d2;
        g3 = vec4(-normalize(cpd - qv.xyz), 0.0); g3.w = d3;

        vec4 g4 = vec4(+normalize(cpa - qv.xyz), 0.0); g4.w = d0;
        vec4 g5 = vec4(+normalize(cpb - qv.xyz), 0.0); g5.w = d1;
        vec4 g6 = vec4(+normalize(cpc - qv.xyz), 0.0); g6.w = d2;
        vec4 g7 = vec4(+normalize(cpd - qv.xyz), 0.0); g7.w = d3;

        vec4 kdopLo;
        kdopLo.x = plaIntersect(ro - qv.xyz, rd, g0);
        kdopLo.y = plaIntersect(ro - qv.xyz, rd, g1);
        kdopLo.z = plaIntersect(ro - qv.xyz, rd, g2);
        kdopLo.w = plaIntersect(ro - qv.xyz, rd, g3);

        vec4 kdopHi;
        kdopHi.x = plaIntersect(ro - qv.xyz, rd, g4);
        kdopHi.y = plaIntersect(ro - qv.xyz, rd, g5);
        kdopHi.z = plaIntersect(ro - qv.xyz, rd, g6);
        kdopHi.w = plaIntersect(ro - qv.xyz, rd, g7);

        vec4 kdopNr = min(kdopLo, kdopHi);
        vec4 kdopFr = max(kdopLo, kdopHi);
        float kdopMn = max(max(kdopNr.x, kdopNr.y), max(kdopNr.z, kdopNr.w));
        float kdopMx = min(min(kdopFr.x, kdopFr.y), min(kdopFr.z, kdopFr.w));        

        if (kdopMn < kdopMx) {
            tuvs[8].x = kdopMn;

            if (kdopMn == kdopNr.x) { tuvs[8].z = 0.0; tuvs[8].y = abs(d0) * sign(meet(qv, ga2)); } //normalize(g0.xyz);
            else if (kdopMn == kdopNr.y) { tuvs[8].z = 1.0; tuvs[8].y = abs(d1) * sign(meet(qv, gb2)); }//normalize(g1.xyz);
            else if (kdopMn == kdopNr.z) { tuvs[8].z = 2.0; tuvs[8].y = abs(d2) * sign(meet(qv, gc2)); } //normalize(g2.xyz);
            else if (kdopMn == kdopNr.w) { tuvs[8].z = 3.0; tuvs[8].y = abs(d3) * sign(meet(qv, gd2)); } //normalize(g3.xyz);
        }
        else {
            tuvs[8].x = -1.;
        }

        //tuvs[8].x = sphIntersect(ro, rd, vec4(q.xyz, distPlaneToOrigin ));
    }


    Payload payload;

    float rm = 1e38f; 			// tracker for minimum ray value
    float tmin = 14.0;
    float tmax = 21.0;
    float t = tmin;
    ro = roStart + t * rd;

    float ow = OUTLINE_WIDTH; 		// outline width
    for (int i =0; i<50; i++) {
        payload = map(ro, rd);
        rm = min(payload.d, rm);

        //check if a ray has passed through an outline region
        if (payload.d > rm && rm < ow * 2.5){
            col = vec3(0); //outline
            break;
        }

        if (payload.d < ow) {
            //color based on suface location
            col = payload.albedo;
            break;
        }

        t += payload.d * .9;
       	ro = roStart + t * rd;//*0.85;
        if (t > tmax) break;
    }

    tuvs[9].x = t;

    vec4 bgcol = vec4(col, 1.0);

    // Sort by hit depth
    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            if (tuvs[j].x > tuvs[j+1].x) {
                vec4 tmp = tuvs[j];
                tuvs[j] = tuvs[j+1];
                tuvs[j+1] = tmp;
            }
        }
    }

    // Composite the W=1 plane
    vec4 rgba = vec4(1.0, 1.0, 1.0, .0);
    for (int i = 0; i < 10; ++i) {
        if( tuvs[i].x>0.0)
        {
            vec3 pos = roStart + tuvs[i].x*rd;  
            float dsam = length(pos-q.xyz);
            float dref = abs(tuvs[i].y);

            float osc = smoothstep(0.0,0.9,  sin((dsam-dref)*80.0))*exp2(-12.0*(dsam-dref)*(dsam-dref));

            vec4 geoCol;
            if (tuvs[i].w < 8.0) {
                vec3 v0, v1, v2;               

                float opacity = min((tuvs[i].z > 0.0 ? 0.3 : .7) + osc * 6., 1.0); 
                vec3 col = tuvs[i].z > 0.0 ? green : emerald;
                geoCol = vec4(col * .8 + .2 * vec3(osc), opacity);
            }
            else if (tuvs[i].w < 9.0) {
                vec3 col = tuvs[i].y > 0.0 ? blue : purple;
                geoCol = vec4(col, min(.2 + osc*.6 , 1.0));
            }
            else geoCol = vec4(col, 1.);            
            rgba = over(rgba, geoCol);
            if (rgba.w >= .99) break;
        }
    }

    return rgba.rgb;
}

mat3 lookAt(in vec3 eye, in vec3 tar, in float r){
    vec3 cw = normalize(tar - eye);// camera w
    vec3 cp = vec3(sin(r), 0., cos(r));// camera up
    vec3 cu = normalize(cross(cw, cp));// camera u
    vec3 cv = normalize(cross(cu, cw));// camera v
    return mat3(cu, cv, cw);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 tot = vec3(0.0);

    // camera
    float an = .2 + -5.0*iMouse.x/iResolution.x;

    float dist = 15.f;
    float fov = 5.f;


    vec3  ro = dist * vec3(cos(3.0*an),sin(3.0*an), .3);
    vec3  ta = vec3(0.0,0.0,0.0);

    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,0.0,1.0) ) );
    vec3 vv = normalize( cross(uu,ww));

    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {           
        //create p for ray based on AA settings
        vec3 p = vec3((-iResolution.xy + 2.0*(fragCoord.xy-0.5+(vec2(float(m),float(n))+0.5)/float(AA))) / iResolution.y,2.0);


        //create view ray from vector p
        vec3 rd = lookAt(ro, ta, 0.)*normalize(vec3(p.xy, 1.0/radians(fov)));// ray direction

        //render scene
        vec3 col = scene(ro,rd);

        //vignette
        //col -= 0.2*length(p.xy);

        tot += col;
    }
    tot /= float(AA*AA);
    fragColor = vec4( tot, 1.0 );
}

