vec3 lineSegmentQuery(in vec3 ro, in vec3 rd, in vec3 s0, in vec3 s1)
{
    vec3 sd = s1 - s0;
    vec3 diff = ro - s0;

    float rdLen2 = dot(rd, rd);
    float sdLen2 = dot(sd, sd);
    float raySegmentDot = -dot(rd, sd);
    float rayStartDot = dot(rd, diff);
    float segmentStartDot = -dot(sd, diff);

    float det = max(rdLen2 * sdLen2 - raySegmentDot * raySegmentDot, 0.0);

    float tRay = 0.0;
    float tSegment = 0.0;

    if (det > 0.0) {
        tSegment = (raySegmentDot * rayStartDot - rdLen2 * segmentStartDot) / det;
        tSegment = clamp(tSegment, 0.0, 1.0); // Ensure tSegment is within the segment bounds
        tRay = (raySegmentDot * segmentStartDot - sdLen2 * rayStartDot) / det;
    } else {
        // Handle the case when determinant is zero or negative
        tRay = -rayStartDot / rdLen2;
    }

    vec3 closestPointOnRay = ro + tRay * rd;
    vec3 closestPointOnSegment = s0 + tSegment * sd;
    vec3 differenceVector = closestPointOnRay - closestPointOnSegment;
    float diffLen2 = dot(differenceVector, differenceVector);

    return vec3(diffLen2, tRay, tSegment);
}


// Returns the "st" parameters defining the closest points between two segments. 
//  P0 / P1 - the start and end points for the first segment
//  Q0 / Q1 - the start and end points for the second segment
vec2 segmentSegmentQuery(vec3 P0, vec3 P1, vec3 Q0, vec3 Q1) {
    vec3 P1mP0 = P1 - P0;
    vec3 Q1mQ0 = Q1 - Q0;
    vec3 P0mQ0 = P0 - Q0;
    float a = dot(P1mP0, P1mP0);
    float b = dot(P1mP0, Q1mQ0);
    float c = dot(Q1mQ0, Q1mQ0);
    float d = dot(P1mP0, P0mQ0);
    float e = dot(Q1mQ0, P0mQ0);
    float det = a * c - b * b;
    float s, t, nd, bmd, bte, ctd, bpe, ate, btd;

    if (det > 0.)
    {
        bte = b * e;
        ctd = c * d;
        if (bte <= ctd)  // s <= 0
        {
            s = 0.;
            if (e <= 0.)  // t <= 0
            {
                // region 6
                t = 0.;
                nd = -d;
                if (nd >= a)
                {
                    s = 1.;
                }
                else if (nd > 0.)
                {
                    s = nd / a;
                }
                // else: s is already zero
            }
            else if (e < c)  // 0 < t < 1
            {
                // region 5
                t = e / c;
            }
            else  // t >= 1
            {
                // region 4
                t = 1.;
                bmd = b - d;
                if (bmd >= a)
                {
                    s = 1.;
                }
                else if (bmd > 0.)
                {
                    s = bmd / a;
                }
                // else:  s is already zero
            }
        }
        else  // s > 0
        {
            s = bte - ctd;
            if (s >= det)  // s >= 1
            {
                // s = 1
                s = 1.;
                bpe = b + e;
                if (bpe <= 0.)  // t <= 0
                {
                    // region 8
                    t = 0.;
                    nd = -d;
                    if (nd <= 0.)
                    {
                        s = 0.;
                    }
                    else if (nd < a)
                    {
                        s = nd / a;
                    }
                    // else: s is already one
                }
                else if (bpe < c)  // 0 < t < 1
                {
                    // region 1
                    t = bpe / c;
                }
                else  // t >= 1
                {
                    // region 2
                    t = 1.;
                    bmd = b - d;
                    if (bmd <= 0.)
                    {
                        s = 0.;
                    }
                    else if (bmd < a)
                    {
                        s = bmd / a;
                    }
                    // else:  s is already one
                }
            }
            else  // 0 < s < 1
            {
                ate = a * e;
                btd = b * d;
                if (ate <= btd)  // t <= 0
                {
                    // region 7
                    t = 0.;
                    nd = -d;
                    if (nd <= 0.)
                    {
                        s = 0.;
                    }
                    else if (nd >= a)
                    {
                        s = 1.;
                    }
                    else
                    {
                        s = nd / a;
                    }
                }
                else  // t > 0
                {
                    t = ate - btd;
                    if (t >= det)  // t >= 1
                    {
                        // region 3
                        t = 1.;
                        bmd = b - d;
                        if (bmd <= 0.)
                        {
                            s = 0.;
                        }
                        else if (bmd >= a)
                        {
                            s = 1.;
                        }
                        else
                        {
                            s = bmd / a;
                        }
                    }
                    else  // 0 < t < 1
                    {
                        // region 0
                        s /= det;
                        t /= det;
                    }
                }
            }
        }
    }
    else
    {
        // The segments are parallel. The quadratic factors to
        //   R(s,t) = a*(s-(b/a)*t)^2 + 2*d*(s - (b/a)*t) + f
        // where a*c = b^2, e = b*d/a, f = |P0-Q0|^2, and b is not
        // zero. R is constant along lines of the form s-(b/a)*t = k
        // and its occurs on the line a*s - b*t + d = 0. This line
        // must intersect both the s-axis and the t-axis because 'a'
        // and 'b' are not zero. Because of parallelism, the line is
        // also represented by -b*s + c*t - e = 0.
        //
        // The code determines an edge of the domain [0,1]^2 that
        // intersects the minimum line, or if none of the edges
        // intersect, it determines the closest corner to the minimum
        // line. The conditionals are designed to test first for
        // intersection with the t-axis (s = 0) using
        // -b*s + c*t - e = 0 and then with the s-axis (t = 0) using
        // a*s - b*t + d = 0.

        // When s = 0, solve c*t - e = 0 (t = e/c).
        if (e <= 0.)  // t <= 0
        {
            // Now solve a*s - b*t + d = 0 for t = 0 (s = -d/a).
            t = 0.;
            nd = -d;
            if (nd <= 0.)  // s <= 0
            {
                // region 6
                s = 0.;
            }
            else if (nd >= a)  // s >= 1
            {
                // region 8
                s = 1.;
            }
            else  // 0 < s < 1
            {
                // region 7
                s = nd / a;
            }
        }
        else if (e >= c)  // t >= 1
        {
            // Now solve a*s - b*t + d = 0 for t = 1 (s = (b-d)/a).
            t = 1.;
            bmd = b - d;
            if (bmd <= 0.)  // s <= 0
            {
                // region 4
                s = 0.;
            }
            else if (bmd >= a)  // s >= 1
            {
                // region 2
                s = 1.;
            }
            else  // 0 < s < 1
            {
                // region 3
                s = bmd / a;
            }
        }
        else  // 0 < t < 1
        {
            // The point (0,e/c) is on the line and domain, so we have
            // one point at which R is a minimum.
            s = 0.;
            t = e / c;
        }
    }

    return vec2(s, t);
}
